#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> res(n);
        // [last y] + [middle n-x-y] + [first x]
        for(int i=0;i<y;i++) res[i]=p[n-y+i];
        int mid=n-x-y;
        for(int i=0;i<mid;i++) res[y+i]=p[x+i];
        for(int i=0;i<x;i++) res[y+mid+i]=p[i];
        p=res;
    };

    auto findPos = [&](int val) -> int {
        for(int i=0;i<n;i++) if(p[i]==val) return i;
        return -1;
    };

    auto newPos = [&](int pos, int x, int y) -> int {
        if(pos < x) return n-x+pos;
        if(pos >= n-y) return pos-(n-y);
        return pos-x+y;
    };

    for(int t=0;t<n;t++){
        int pos=findPos(t+1);
        if(pos==t) continue;
        // Try single operation
        bool found=false;
        for(int x=1;x<n && !found;x++){
            for(int y=1;x+y<n && !found;y++){
                if(newPos(pos,x,y)==t){
                    doOp(x,y);
                    found=true;
                }
            }
        }
        if(found) continue;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
